import { MAX_BLURRED_LAYERS } from "./device-tier";

/**
 * Caps how many surfaces may run `backdrop-filter` simultaneously.
 *
 * Blur cost is per-composited-layer and it compounds: three stacked blurred
 * layers on a budget Android is a visibly janky scroll, and our users are on
 * exactly that hardware, in a gym, on battery, all day. Rather than trusting
 * every future component author to remember this, the GlassSurface primitive
 * registers here and is TOLD whether it may blur.
 *
 * Grants go to the highest-priority registrants, ties broken by registration
 * order. Chrome (nav bars, tab bars, sheets) outranks content, which is
 * correct — those are the surfaces the design language actually needs
 * floating.
 *
 * Callers pass a stable id (React's useId), so registration never requires
 * component state.
 */

export type BlurPriority = number;

interface Registration {
  id: string;
  priority: BlurPriority;
  seq: number;
}

let seq = 0;
const registrations = new Map<string, Registration>();
let granted = new Set<string>();
const listeners = new Set<() => void>();

function recompute() {
  const winners = [...registrations.values()]
    .sort((a, b) => b.priority - a.priority || a.seq - b.seq)
    .slice(0, MAX_BLURRED_LAYERS)
    .map((r) => r.id);

  const next = new Set(winners);
  const changed =
    next.size !== granted.size || [...next].some((id) => !granted.has(id));

  if (changed) {
    granted = next;
    listeners.forEach((l) => l());
  }
}

export function registerBlurLayer(id: string, priority: BlurPriority): void {
  registrations.set(id, { id, priority, seq: seq++ });
  recompute();
}

export function unregisterBlurLayer(id: string): void {
  registrations.delete(id);
  granted.delete(id);
  recompute();
}

export function isBlurGranted(id: string): boolean {
  return granted.has(id);
}

export function subscribeBlurBudget(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** Standard priorities, so callers don't invent magic numbers. */
export const BLUR_PRIORITY = {
  /** Top nav / tab bar — the surfaces the design language needs floating. */
  chrome: 100,
  /** Modal sheets and floating actions, while open. */
  overlay: 80,
  /** Anything else. Usually loses, which is the intended outcome. */
  content: 10,
} as const;
